changeSet.sql:
ALTER TABLE auditoria.CAMPO_ALTERADO
    DROP CONSTRAINT FK_CAMPO_ALTERADO_REGISTRO_AUDITORIA;

ALTER TABLE auditoria.REGISTRO_AUDITORIA RENAME TO AUDIT_OPERATION;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN ID_REGISTRO_AUDITORIA TO ID_AUDIT_OPERATION;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN NM_ENTIDADE TO NM_ENTITY;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN ID_REGISTRO_AFETADO TO DS_ENTITY_ID;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN CD_OPERACAO TO CD_OPERATION;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN DT_OPERACAO TO DT_OPERATION;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN ID_AUTOR TO ID_ACTOR;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN NM_AUTOR TO NM_ACTOR;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN CD_CORRELACAO TO CD_CORRELATION;
ALTER TABLE auditoria.AUDIT_OPERATION
    ALTER COLUMN DS_ENTITY_ID TYPE VARCHAR(255) USING DS_ENTITY_ID::text;
ALTER TABLE auditoria.AUDIT_OPERATION
    ALTER COLUMN ID_ACTOR TYPE VARCHAR(200) USING ID_ACTOR::text;
ALTER TABLE auditoria.AUDIT_OPERATION
    ALTER COLUMN CD_CORRELATION TYPE VARCHAR(200);
UPDATE auditoria.AUDIT_OPERATION SET CD_OPERATION = CASE CD_OPERATION
    WHEN 'INSERCAO' THEN 'INSERT'
    WHEN 'ALTERACAO' THEN 'UPDATE'
    WHEN 'EXCLUSAO' THEN 'DELETE'
    ELSE CD_OPERATION END;
ALTER TABLE auditoria.AUDIT_OPERATION ADD COLUMN CD_ACTOR_TYPE VARCHAR(20);
UPDATE auditoria.AUDIT_OPERATION SET CD_ACTOR_TYPE = CASE
    WHEN ID_ACTOR IS NULL THEN 'TECNICO' ELSE 'USUARIO' END;
ALTER TABLE auditoria.AUDIT_OPERATION ALTER COLUMN CD_ACTOR_TYPE SET NOT NULL;

ALTER TABLE auditoria.CAMPO_ALTERADO RENAME TO AUDIT_CHANGE;
ALTER TABLE auditoria.AUDIT_CHANGE RENAME COLUMN ID_CAMPO_ALTERADO TO ID_AUDIT_CHANGE;
ALTER TABLE auditoria.AUDIT_CHANGE RENAME COLUMN ID_REGISTRO_AUDITORIA TO ID_AUDIT_OPERATION;
ALTER TABLE auditoria.AUDIT_CHANGE RENAME COLUMN NM_CAMPO TO NM_FIELD;
ALTER TABLE auditoria.AUDIT_CHANGE RENAME COLUMN DS_VALOR_ANTERIOR TO DS_OLD_VALUE;
ALTER TABLE auditoria.AUDIT_CHANGE RENAME COLUMN DS_VALOR_NOVO TO DS_NEW_VALUE;
ALTER TABLE auditoria.AUDIT_CHANGE ADD CONSTRAINT FK_AUDIT_CHANGE_OPERATION
    FOREIGN KEY (ID_AUDIT_OPERATION)
    REFERENCES auditoria.AUDIT_OPERATION (ID_AUDIT_OPERATION);

ALTER INDEX auditoria.IDX_REGISTRO_AUDITORIA_ENTIDADE RENAME TO IDX_AUDIT_OPERATION_ENTITY;
ALTER INDEX auditoria.IDX_CAMPO_ALTERADO_REGISTRO RENAME TO IDX_AUDIT_CHANGE_OPERATION;

rollback.sql:
ALTER TABLE auditoria.AUDIT_CHANGE DROP CONSTRAINT FK_AUDIT_CHANGE_OPERATION;
ALTER INDEX auditoria.IDX_AUDIT_OPERATION_ENTITY RENAME TO IDX_REGISTRO_AUDITORIA_ENTIDADE;
ALTER INDEX auditoria.IDX_AUDIT_CHANGE_OPERATION RENAME TO IDX_CAMPO_ALTERADO_REGISTRO;

ALTER TABLE auditoria.AUDIT_CHANGE RENAME COLUMN DS_NEW_VALUE TO DS_VALOR_NOVO;
ALTER TABLE auditoria.AUDIT_CHANGE RENAME COLUMN DS_OLD_VALUE TO DS_VALOR_ANTERIOR;
ALTER TABLE auditoria.AUDIT_CHANGE RENAME COLUMN NM_FIELD TO NM_CAMPO;
ALTER TABLE auditoria.AUDIT_CHANGE RENAME COLUMN ID_AUDIT_OPERATION TO ID_REGISTRO_AUDITORIA;
ALTER TABLE auditoria.AUDIT_CHANGE RENAME COLUMN ID_AUDIT_CHANGE TO ID_CAMPO_ALTERADO;
ALTER TABLE auditoria.AUDIT_CHANGE RENAME TO CAMPO_ALTERADO;

ALTER TABLE auditoria.AUDIT_OPERATION DROP COLUMN CD_ACTOR_TYPE;
UPDATE auditoria.AUDIT_OPERATION SET CD_OPERATION = CASE CD_OPERATION
    WHEN 'INSERT' THEN 'INSERCAO'
    WHEN 'UPDATE' THEN 'ALTERACAO'
    WHEN 'DELETE' THEN 'EXCLUSAO'
    ELSE CD_OPERATION END;
ALTER TABLE auditoria.AUDIT_OPERATION
    ALTER COLUMN ID_ACTOR TYPE UUID USING NULLIF(ID_ACTOR, '')::uuid;
ALTER TABLE auditoria.AUDIT_OPERATION
    ALTER COLUMN DS_ENTITY_ID TYPE UUID USING DS_ENTITY_ID::uuid;
ALTER TABLE auditoria.AUDIT_OPERATION
    ALTER COLUMN CD_CORRELATION TYPE VARCHAR(64);
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN CD_CORRELATION TO CD_CORRELACAO;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN NM_ACTOR TO NM_AUTOR;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN ID_ACTOR TO ID_AUTOR;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN CD_OPERATION TO CD_OPERACAO;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN DT_OPERATION TO DT_OPERACAO;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN DS_ENTITY_ID TO ID_REGISTRO_AFETADO;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN NM_ENTITY TO NM_ENTIDADE;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME COLUMN ID_AUDIT_OPERATION TO ID_REGISTRO_AUDITORIA;
ALTER TABLE auditoria.AUDIT_OPERATION RENAME TO REGISTRO_AUDITORIA;
ALTER TABLE auditoria.CAMPO_ALTERADO ADD CONSTRAINT FK_CAMPO_ALTERADO_REGISTRO_AUDITORIA
    FOREIGN KEY (ID_REGISTRO_AUDITORIA)
    REFERENCES auditoria.REGISTRO_AUDITORIA (ID_REGISTRO_AUDITORIA);
